-- Theme setup: Matugen colours (generated by noctalia) with a transparent
-- background, so the terminal and compositor provide the opacity and blur.

-- Let the terminal's background show through these parts of Neovim.
local function transparent_background()
	-- Each name is a highlight group controlling a particular part of the UI.
	for _, group in ipairs({
		"Normal", -- Text and background in the active window.
		"NormalNC", -- Text and background in inactive windows.
		"SignColumn", -- Gutter containing diagnostic and Git signs.
		"LineNr", -- Line numbers.
		"CursorLineNr", -- Line number on the cursor line.
		"FoldColumn", -- Fold markers in the gutter.
		"EndOfBuffer", -- Empty lines below the end of a file.
		"NormalFloat", -- Default background of floating windows.
		"FloatBorder", -- Borders around floating windows.
	}) do
		-- Read the group's current colours and styling (0 = global highlights).
		-- Resolve linked groups so their foreground and styling are preserved too.
		local hl = vim.api.nvim_get_hl(0, { name = group, link = false })
		-- Remove only the background colour, keeping everything else.
		hl.bg = nil
		vim.api.nvim_set_hl(0, group, hl)
	end

	-- mini.statuscolumn works out its dimmed inactive-window colour once, when
	-- its setup runs (before the theme exists), and never updates it. Set it
	-- from the theme's Comment colour, with no background so it stays transparent.
	local comment = vim.api.nvim_get_hl(0, { name = "Comment", link = false })
	vim.api.nvim_set_hl(0, "MiniStatuscolumnDim", { fg = comment.fg })
end

-- base16 doesn't fire ColorScheme, so plugins and the transparency autocmd
-- below miss theme changes, including noctalia's live reloads (SIGUSR1).
-- Wrap its setup to fire the event. Scheduled so it runs after the generated
-- matugen setup has also set its own highlights.
local base16_ok, base16 = pcall(require, "base16-colorscheme")
if base16_ok then
	local base16_setup = base16.setup
	base16.setup = function(...)
		base16_setup(...)
		vim.schedule(function()
			vim.api.nvim_exec_autocmds("ColorScheme", { modeline = false })
		end)
	end
end

-- A colourscheme can restore opaque backgrounds, so clear them again when
-- Neovim fires ColorScheme. Schedule this to run after theme setup finishes.
vim.api.nvim_create_autocmd("ColorScheme", {
	callback = function()
		vim.schedule(transparent_background)
	end,
})

-- Load the Matugen colours when present.
local matugen_ok, matugen = pcall(require, "matugen")
if matugen_ok then
	matugen.setup()
end

-- Apply once now: the initial Matugen setup above has already finished.
transparent_background()
